begin;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-0000-0000-000000000981','template-owner@test.local'),('00000000-0000-0000-0000-000000000982','template-reader@test.local');
insert into public.companies(id,legal_name,display_name,created_by) values ('10000000-0000-0000-0000-000000000981','Template A','Template A','00000000-0000-0000-0000-000000000981'),('10000000-0000-0000-0000-000000000982','Template B','Template B','00000000-0000-0000-0000-000000000981');
insert into public.company_memberships(company_id,user_id,role) values ('10000000-0000-0000-0000-000000000981','00000000-0000-0000-0000-000000000981','owner'),('10000000-0000-0000-0000-000000000981','00000000-0000-0000-0000-000000000982','auditor');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000981';
select lives_ok($$insert into public.invoice_templates(company_id,settings) values ('10000000-0000-0000-0000-000000000981','{"businessName":"Updated business","phone":"555-0100"}')$$,'owner can save template');
select is((select settings->>'phone' from public.invoice_templates where company_id='10000000-0000-0000-0000-000000000981'),'555-0100','business contact details persist');
select throws_ok($$insert into public.invoice_templates(company_id,settings) values ('10000000-0000-0000-0000-000000000982','{}')$$,'42501',null,'cannot save another company template');
select throws_ok($$update public.invoice_templates set company_id='10000000-0000-0000-0000-000000000982' where company_id='10000000-0000-0000-0000-000000000981'$$,'42501',null,'cannot transfer template to another company');
select throws_ok($$update public.invoice_templates set settings='[]' where company_id='10000000-0000-0000-0000-000000000981'$$,'23514',null,'settings must be an object');
select throws_ok($$update public.invoice_templates set settings=jsonb_build_object('logo',repeat('x',500001)) where company_id='10000000-0000-0000-0000-000000000981'$$,'23514',null,'stored template size is bounded');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000982';
select is((select count(*) from public.invoice_templates),1::bigint,'auditor can read template');
update public.invoice_templates set settings='{}';
select is((select settings->>'phone' from public.invoice_templates),'555-0100','auditor cannot change template');
reset role;
update public.company_memberships set is_active=false where user_id='00000000-0000-0000-0000-000000000982';
set local role authenticated;
select is((select count(*) from public.invoice_templates),0::bigint,'inactive member cannot read template');
select ok(not has_table_privilege('anon','public.invoice_templates','select'),'anonymous cannot read template');
select * from finish();rollback;
